using TMPro;
using UnityEngine;

/// <summary>
/// Gameplay UI theme: "Sci-Fi UI" (GUI skin textures + Zekton font) and "MK Easy Text" baked effect fonts.
/// Lives at Assets/Resources/UITheme.asset (generated by the editor; edit freely). Every field is optional:
/// missing art falls back to the plain runtime UI, so removing a pack never breaks the game.
/// </summary>
[CreateAssetMenu(menuName = "Grab & Go/UI Theme", fileName = "UITheme")]
public class UITheme : ScriptableObject
{
    public enum Fancy { Gold, Neon, Purple }

    [System.Serializable]
    public class Slice
    {
        public Texture2D texture;
        [Tooltip("9-slice border in texture pixels (left, bottom, right, top).")]
        public Vector4 border;
        [Tooltip("Higher = thinner borders on screen.")]
        public float borderScale = 6f;
        [System.NonSerialized] public Sprite sprite;

        public Sprite GetSprite()
        {
            if (sprite == null && texture != null)
                sprite = Sprite.Create(texture, new Rect(0, 0, texture.width, texture.height), new Vector2(0.5f, 0.5f),
                                       100f, 0, SpriteMeshType.FullRect, border);
            return sprite;
        }
    }

    public int generatorVersion;

    [Header("Sci-Fi UI skin")]
    public Slice window = new Slice();
    public Slice button = new Slice();
    public Slice buttonActive = new Slice();
    public Slice barFrame = new Slice();
    [Tooltip("Light capsule, tinted at runtime (pressure meter fill).")]
    public Slice barFill = new Slice();
    public Slice barRed = new Slice();

    [Header("Space Exploration GUI Kit (gameplay HUD)")]
    [Tooltip("Framed panel behind every in-game HUD element.")]
    public Slice hudPanel = new Slice();
    public Texture2D iconTimer;
    public Texture2D iconPressure;
    public Texture2D iconStatus;
    public Texture2D iconAbility;

    [Header("Fonts")]
    [Tooltip("Sci-Fi UI font used for all HUD text (converted to a TextMeshPro font at runtime).")]
    public Font hudFont;
    [Tooltip("MK Easy Text baked fonts for headlines.")]
    public Font goldFont;
    public Font neonFont;
    public Font purpleFont;

    // ---------- runtime access ----------
    private static UITheme s_active;
    private static bool s_loaded;
    public static UITheme Active
    {
        get
        {
            if (!s_loaded)
            {
                s_loaded = true;
                s_active = Resources.Load<UITheme>("UITheme");
            }
            return s_active;
        }
    }

    [System.NonSerialized] private TMP_FontAsset _hudFontAsset;
    [System.NonSerialized] private bool _hudFontTried;

    /// <summary>The Sci-Fi font as a dynamic TMP font asset (null if unavailable; callers keep the default font).</summary>
    public TMP_FontAsset HudFontAsset
    {
        get
        {
            if (!_hudFontTried)
            {
                _hudFontTried = true;
                if (hudFont != null)
                {
                    try
                    {
                        _hudFontAsset = TMP_FontAsset.CreateFontAsset(hudFont);
                        if (_hudFontAsset != null)
                        {
                            _hudFontAsset.name = hudFont.name + " (runtime TMP)";
                            // Keep the default TMP font as a fallback for any symbol Zekton lacks (arrows, dots).
                            var fallback = TMP_Settings.defaultFontAsset;
                            if (fallback != null && _hudFontAsset.fallbackFontAssetTable != null)
                                _hudFontAsset.fallbackFontAssetTable.Add(fallback);
                        }
                    }
                    catch (System.Exception e)
                    {
                        Debug.LogWarning($"[UITheme] Could not create a TMP font from {hudFont.name}: {e.Message}");
                    }
                }
            }
            return _hudFontAsset;
        }
    }

    [System.NonSerialized] private Material _hudTextMaterial;

    /// <summary>The HUD font's material with an outline and drop shadow, so text reads on any background.</summary>
    public Material HudTextMaterial
    {
        get
        {
            if (_hudTextMaterial == null && HudFontAsset != null)
            {
                _hudTextMaterial = new Material(HudFontAsset.material) { name = "HUD Text (outlined)" };
                _hudTextMaterial.EnableKeyword(ShaderUtilities.Keyword_Outline);
                _hudTextMaterial.SetFloat(ShaderUtilities.ID_OutlineWidth, 0.17f);
                _hudTextMaterial.SetColor(ShaderUtilities.ID_OutlineColor, new Color(0.07f, 0.04f, 0.2f, 1f));
                _hudTextMaterial.EnableKeyword(ShaderUtilities.Keyword_Underlay);
                _hudTextMaterial.SetColor(ShaderUtilities.ID_UnderlayColor, new Color(0f, 0f, 0f, 0.55f));
                _hudTextMaterial.SetFloat(ShaderUtilities.ID_UnderlayOffsetX, 0.45f);
                _hudTextMaterial.SetFloat(ShaderUtilities.ID_UnderlayOffsetY, -0.55f);
            }
            return _hudTextMaterial;
        }
    }

    public Font FancyFont(Fancy style) => style == Fancy.Gold ? goldFont : style == Fancy.Neon ? neonFont : purpleFont;
}
